<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantConfig\Domain\ValueObject\Holder\TenantConfigDisabledUserEmailAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantConfigDisabledUserEmailAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TenantConfigDisabledUserEmailAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getDisabledUserEmail returns null on a freshly created holder.
     */
    public function testDisabledUserEmailNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigDisabledUserEmailAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isDisabledUserEmailAssigned());
        $this->assertNull($holder->getDisabledUserEmail());
    }
}
class ImplWithTenantConfigDisabledUserEmailAttributeHolderUnitTest
{
    use TenantConfigDisabledUserEmailAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedDisabledUserEmailRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultDisabledUserEmail();
    }
}
